using ImageMagick;
using PdfSharp.Pdf;
using PdfSharp.Pdf.IO;
using System.Security.Cryptography;
namespace Tangerine;

internal static class BatchAudit
{
    internal static async Task Run(App app, string directory)
    {
        directory = Path.GetFullPath(directory); Directory.CreateDirectory(directory); var output = Path.Combine(directory, "outputs"); Directory.CreateDirectory(output);
        var settings = new AppSettings { OutputDirectory = output, EngineDirectory = Environment.GetEnvironmentVariable("TANGERINE_ENGINE_DIR") ?? app.Settings.EngineDirectory }; var engine = new Engine(settings); var reports = new List<object>();
        async Task Test(string name, Func<Task> run) { try { await run(); reports.Add(new { name, passed = true }); } catch (Exception ex) { reports.Add(new { name, passed = false, error = ex.ToString() }); } File.WriteAllText(Path.Combine(directory, "batch-results.json"), JsonSerializer.Serialize(reports, new JsonSerializerOptions { WriteIndented = true })); }
        void Check(bool ok, string reason) { if (!ok) throw new InvalidDataException(reason); }
        WheelItem Item(string id) => Catalog.Tools("sample.jpg", 3).Concat(Catalog.Tools("sample.mp4", 2)).Concat(Catalog.Tools("sample.wav", 2)).Concat(Catalog.Tools("sample.pdf", 2)).Concat(Catalog.Conversions("sample.jpg")).Concat(Catalog.Conversions("sample.png")).Concat(Catalog.Conversions("sample.mp4")).First(x => x.Id == id);
        string Photo(string folder, string name, int w, int h) { var dir = Path.Combine(directory, folder); Directory.CreateDirectory(dir); var path = Path.Combine(dir, name); using var image = new MagickImage("gradient:#F89432-#327150", (uint)w, (uint)h); image.SetAttribute("comment", "private batch fixture"); image.Write(path); return path; }
        var a = Photo("source-a", "Oranges.png", 200, 120); var b = Photo("source-b", "Oranges.jpg", 400, 240); var c = Photo("source-c", "Oranges.png", 90, 180); var images = new[] { a, b, c };
        var audio = Path.Combine(directory, "Voice.wav"); await Engine.Process(engine.Ffmpeg, new[] { "-v", "error", "-nostdin", "-f", "lavfi", "-i", "sine=frequency=440:duration=2", "-ac", "2", audio }, CancellationToken.None);
        var audio2 = Path.Combine(directory, "Voice 2.wav"); File.Copy(audio, audio2);
        var video = Path.Combine(directory, "Clip.mp4"); await Engine.Process(engine.Ffmpeg, new[] { "-v", "error", "-nostdin", "-loop", "1", "-i", a, "-i", audio, "-t", "2", "-c:v", "libx264", "-preset", "ultrafast", "-pix_fmt", "yuv420p", "-c:a", "aac", video }, CancellationToken.None);
        var video2 = Path.Combine(directory, "Clip 2.mp4"); File.Copy(video, video2);
        string Pdf(string name, int pages) { var path = Path.Combine(directory, name); using var doc = new PdfDocument(); for (int i = 0; i < pages; i++) { var page = doc.AddPage(); page.Width = PdfSharp.Drawing.XUnit.FromPoint(200 + i * 20); page.Height = PdfSharp.Drawing.XUnit.FromPoint(300); } doc.Save(path); return path; }
        var pdf = Pdf("Pages.pdf", 2); var pdf2 = Pdf("Pages 2.pdf", 3);
        var originalPaths = images.Concat(new[] { audio, audio2, video, video2, pdf, pdf2 }).ToArray(); var hashes = originalPaths.ToDictionary(p => p, p => SHA256.HashData(File.ReadAllBytes(p)));
        async Task<BatchPlan> Run(string[] files, string id, WheelMode mode, OperationOptions? options = null) { var plan = new BatchPlan(files, Item(id), mode); if (options != null) await plan.SetCommon(files[0], options, engine, CancellationToken.None); await BatchRunner.Run(plan, engine, 82, CancellationToken.None); Check(plan.Entries.All(e => e.State == "Done"), string.Join("; ", plan.Entries.Select(e => e.Input + ": " + e.Error))); return plan; }
        await Test("Multi-image menu retains all single-file tools", () => { var tools = Catalog.ToolsForSelection(images); Check(new[] { "compress", "metadata", "crop", "edit", "annotate", "background", "redact", "collage", "createpdf" }.All(id => tools.Any(x => x.Id == id)), "Missing image batch tool"); return Task.CompletedTask; });
        await Test("Video snapshots and PDF organization remain available in batches", () => { Check(Catalog.ToolsForSelection(new[] { video, video2 }).Any(x => x.Id == "snapshot") && Catalog.ToolsForSelection(new[] { video, video2 }).Any(x => x.Id == "join"), "Video menu replaced a tool"); Check(Catalog.ToolsForSelection(new[] { pdf, pdf2 }).Any(x => x.Id == "organize") && Catalog.ToolsForSelection(new[] { pdf, pdf2 }).Any(x => x.Id == "merge"), "PDF menu replaced a tool"); return Task.CompletedTask; });
        await Test("Mixed source conversion menus include only common targets", () => { var common = Catalog.ConversionsForSelection(new[] { a, pdf }); Check(common.Any(x => x.Id == "png") && !common.Any(x => x.Id == "docx"), "Incorrect mixed conversion intersection"); Check(!Catalog.ConversionsForSelection(new[] { video, "animation.gif" }).Any(x => x.Id == "mp3"), "GIF offered audio extraction"); Check(!Catalog.ToolsForSelection(new[] { pdf, video }).Any(x => x.Id == "split"), "Different split operations were combined"); return Task.CompletedTask; });
        await Test("Selection deduplicates repeated paths and casing", () => { Check(new BatchPlan(new[] { a, a.ToUpperInvariant(), b }, Item("png"), WheelMode.Convert).Entries.Count == 2, "Duplicate paths retained"); return Task.CompletedTask; });
        await Test("Three image conversions produce separate collision-safe outputs", async () => { var plan = await Run(images, "png", WheelMode.Convert); var paths = plan.Entries.SelectMany(e => e.Outputs).ToArray(); Check(paths.Length == 3 && paths.Distinct(StringComparer.OrdinalIgnoreCase).Count() == 3, "Outputs collided"); foreach (var p in paths) { using var image = new MagickImage(p); Check(image.Width > 0, "Invalid output"); } });
        await Test("Default destination is beside each source, including an existing target format", async () => { var plan = new BatchPlan(images, Item("png"), WheelMode.Convert); await BatchRunner.Run(plan, new Engine(new() { EngineDirectory = settings.EngineDirectory }), 82, CancellationToken.None); Check(plan.Entries.All(e => e.State == "Done" && Path.GetDirectoryName(e.Outputs.Single()) == Path.GetDirectoryName(e.Input) && e.Outputs.Single() != e.Input), "Output location or source preservation is wrong"); });
        foreach (var id in new[] { "compress", "metadata", "crop", "edit", "annotate", "background", "redact" }) await Test("Three-file image tool: " + id, async () =>
        {
            var options = new OperationOptions { X = 20, Y = 12, Width = 100, Height = 60, FontSize = 18, Brightness = 65, Text = "Batch", MaxDimension = 160 }; var plan = await Run(images, id, WheelMode.Tools, options);
            for (int i = 0; i < plan.Entries.Count; i++) { using var result = new MagickImage(plan.Entries[i].Outputs.Single()); if (id == "crop") { using var source = new MagickImage(images[i]); Check(result.Width == source.Width / 2 && result.Height == source.Height / 2, "Relative crop dimensions are incorrect"); } if (id == "compress") Check(result.Width <= 160 && result.Height <= 160, "Shared size setting ignored"); if (id == "metadata") Check(result.GetAttribute("comment") == null, "Metadata remains"); }
        });
        await Test("Custom crop overrides shared settings without changing other files", async () => { var plan = new BatchPlan(images, Item("crop"), WheelMode.Tools); await plan.SetCommon(a, new() { X = 0, Y = 0, Width = 100, Height = 60 }, engine, CancellationToken.None); plan.Entries[1].CustomOptions = new() { X = 5, Y = 6, Width = 40, Height = 30 }; await BatchRunner.Run(plan, engine, 82, CancellationToken.None); using var first = new MagickImage(plan.Entries[0].Outputs.Single()); using var second = new MagickImage(plan.Entries[1].Outputs.Single()); Check(first.Width == 100 && second.Width == 40 && second.Height == 30, "Per-file options were lost"); });
        await Test("Exact-pixel selection can be used instead of proportional scaling", async () => { var plan = new BatchPlan(new[] { a, b }, Item("crop"), WheelMode.Tools) { ScaleSelection = false }; await plan.SetCommon(a, new() { X = 1, Y = 1, Width = 40, Height = 30 }, engine, CancellationToken.None); await BatchRunner.Run(plan, engine, 82, CancellationToken.None); foreach (var e in plan.Entries) { using var image = new MagickImage(e.Outputs.Single()); Check(image.Width == 40 && image.Height == 30, "Exact-pixel mode changed dimensions"); } });
        await Test("A bad middle file does not discard successful files or stop later files", async () => { var bad = Path.Combine(directory, "Broken.png"); File.WriteAllText(bad, "invalid image"); var plan = new BatchPlan(new[] { a, bad, b }, Item("webp"), WheelMode.Convert); await BatchRunner.Run(plan, engine, 82, CancellationToken.None); Check(plan.Entries[0].State == "Done" && plan.Entries[1].State == "Failed" && plan.Entries[1].Error.Length > 0 && plan.Entries[2].State == "Done", "Batch did not isolate a file failure"); Check(plan.Entries.Where(e => e.State == "Done").All(e => e.Outputs.All(File.Exists)), "Successful outputs were discarded"); });
        await Test("Missing source is reported per file and remaining files continue", async () => { var plan = new BatchPlan(new[] { Path.Combine(directory, "missing.png"), a }, Item("webp"), WheelMode.Convert); await BatchRunner.Run(plan, engine, 82, CancellationToken.None); Check(plan.Entries[0].State == "Failed" && plan.Entries[1].State == "Done", "Missing file stopped batch"); });
        await Test("Cancellation keeps completed files and skips the rest", async () => { using var cancel = new CancellationTokenSource(); var plan = new BatchPlan(images, Item("webp"), WheelMode.Convert); await BatchRunner.Run(plan, engine, 82, cancel.Token, e => { if (e.State == "Done") cancel.Cancel(); }); Check(plan.Entries[0].State == "Done" && File.Exists(plan.Entries[0].Outputs.Single()) && plan.Entries.Skip(1).All(e => e.State == "Cancelled" && e.Outputs.Count == 0), "Cancellation lost completed work or processed later files"); });
        await Test("Cancellation before processing produces no outputs", async () => { using var cancel = new CancellationTokenSource(); cancel.Cancel(); var plan = new BatchPlan(images, Item("webp"), WheelMode.Convert); await BatchRunner.Run(plan, engine, 82, cancel.Token); Check(plan.Entries.All(e => e.State == "Cancelled" && e.Outputs.Count == 0), "Cancelled batch wrote outputs"); });
        await Test("Cancellation when a current item starts creates no partial outputs", async () => { using var cancel = new CancellationTokenSource(); var plan = new BatchPlan(new[] { video, video2 }, Item("webm"), WheelMode.Convert); await BatchRunner.Run(plan, engine, 82, cancel.Token, e => { if (e.State == "Processing") cancel.Cancel(); }); Check(plan.Entries.All(e => e.State == "Cancelled" && e.Outputs.Count == 0), "Current item survived cancellation"); });
        await Test("Mixed image and PDF conversion preserves per-source output groups", async () => { var plan = await Run(new[] { a, pdf }, "png", WheelMode.Convert); Check(File.Exists(plan.Entries[0].Outputs.Single()) && Directory.GetFiles(plan.Entries[1].Outputs.Single(), "*.png").Length == 2, "PDF pages were not grouped by source"); });
        foreach (var id in new[] { "compress", "metadata", "trim", "normalize", "channels", "bleep", "visualize" }) await Test("Two-file audio tool: " + id, async () => { var plan = await Run(new[] { audio, audio2 }, id, WheelMode.Tools, new() { Start = .2, Duration = .7, Channels = 1, BleepRanges = new() { new(.2, .5), new(1, 1.3) } }); foreach (var e in plan.Entries) await Engine.Process(engine.Ffmpeg, new[] { "-v", "error", "-nostdin", "-i", e.Outputs.Single(), "-f", "null", "-" }, CancellationToken.None); });
        foreach (var id in new[] { "compress", "metadata", "mute", "trim", "crop", "speed", "snapshot", "split", "redact" }) await Test("Two-file video tool: " + id, async () => { var plan = await Run(new[] { video, video2 }, id, WheelMode.Tools, new() { X = 10, Y = 10, Width = 100, Height = 60, Start = .2, Duration = .7, Speed = 2, SnapshotTimes = new() { .2, 1 }, SplitPoints = new() { 1 } }); foreach (var e in plan.Entries) { if (id == "snapshot") Check(Directory.GetFiles(e.Outputs.Single(), "*.png").Length == 2, "Snapshot count differs"); else if (id == "split") Check(Directory.GetFiles(e.Outputs.Single(), "*.mp4").Length == 2, "Split count differs"); else await Engine.Process(engine.Ffmpeg, new[] { "-v", "error", "-nostdin", "-i", e.Outputs.Single(), "-f", "null", "-" }, CancellationToken.None); } });
        foreach (var id in new[] { "compress", "metadata", "split", "organize" }) await Test("Two-file PDF tool: " + id, async () => { var plan = await Run(new[] { pdf, pdf2 }, id, WheelMode.Tools, new() { PageEdits = new() { new(2, 90), new(1) } }); for (int i = 0; i < 2; i++) { if (id == "split") Check(Directory.GetFiles(plan.Entries[i].Outputs.Single(), "*.pdf").Length == i + 2, "Split omitted pages"); else { using var result = PdfReader.Open(plan.Entries[i].Outputs.Single(), PdfDocumentOpenMode.Import); Check(result.PageCount == (id == "organize" ? 2 : i + 2), "Wrong page count"); } } });
        await Test("Different PDFs can have independent page edits", async () => { var plan = new BatchPlan(new[] { pdf, pdf2 }, Item("organize"), WheelMode.Tools); plan.Entries[0].CustomOptions = new() { PageEdits = new() { new(2, 90) } }; plan.Entries[1].CustomOptions = new() { PageEdits = new() { new(3), new(1) } }; await BatchRunner.Run(plan, engine, 82, CancellationToken.None); using var second = PdfReader.Open(plan.Entries[1].Outputs.Single(), PdfDocumentOpenMode.Import); Check(second.PageCount == 2 && second.Pages[0].Width.Point == 240, "Per-file PDF order was ignored"); });
        foreach (var group in new[] { (Id: "createpdf", Files: images), (Id: "collage", Files: images), (Id: "join", Files: new[] { video, video2 }), (Id: "merge", Files: new[] { pdf, pdf2 }) }) await Test("Combined operation remains available: " + group.Id, async () => { var result = await engine.Run(group.Files, Item(group.Id), WheelMode.Tools, new(), CancellationToken.None); Check(result.Count == 1 && File.Exists(result[0]), "Combined operation was split into separate outputs"); });
        await Test("Restored compression controls retain values and selected dropdown", async () => { var window = new OptionsWindow(new[] { a }, Item("compress"), settings, new() { Quality = 45, MaxDimension = 1280, StripMetadata = false }); try { window.Show(); await Task.Delay(80); await window.Ready; var o = window.ReadOptions(); Check(o.Quality == 45 && o.MaxDimension == 1280 && !o.StripMetadata, "Shared settings were reset on reopen"); var combo = Descendants<ComboBox>(window).Single(); Check(combo.SelectedIndex == 3, "Dropdown does not display saved setting"); Check(Descendants<CheckBox>(window).Single().IsChecked == false, "Checkbox does not display saved setting"); } finally { window.Close(); } });
        await Test("Restored image editor exports saved crop dimensions", async () => { var window = new OptionsWindow(new[] { b }, Item("crop"), settings, new() { X = 10, Y = 20, Width = 100, Height = 80 }); try { window.Show(); await Task.Delay(80); await window.Ready; var o = window.ReadOptions(); Check(o.X == 10 && o.Y == 20 && o.Width == 100 && o.Height == 80, "Crop editor discarded custom options"); } finally { window.Close(); } });
        await Test("Restored audio trim does not revert to the full duration", async () => { var window = new OptionsWindow(new[] { audio }, Item("trim"), settings, new() { Start = .3, Duration = .8 }); try { window.Show(); await Task.Delay(80); await window.Ready; var o = window.ReadOptions(); Check(Math.Abs(o.Start - .3) < .01 && Math.Abs(o.Duration - .8) < .01, "Media initialization overwrote saved range"); } finally { window.Close(); } });
        await Test("Restored PDF page cards keep per-file rotations and order", async () => { var window = new OptionsWindow(new[] { pdf2 }, Item("organize"), settings, new() { PageEdits = new() { new(3, 90), new(1) } }); try { window.Show(); await Task.Delay(80); await window.Ready; Check(window.ReadOptions().PageEdits.SequenceEqual(new[] { new PdfPageChoice(3, 90), new PdfPageChoice(1) }), "PDF cards lost custom edits"); } finally { window.Close(); } });
        await Test("Batch panel adds files, removes duplicates and runs every row", async () => { var window = new BatchWindow(app, new[] { a, b }, Item("webp"), WheelMode.Convert, settings); try { window.Show(); window.AddFiles(new[] { c, a }); await Task.Delay(100); Check(window.Plan.Entries.Count == 3, "Add files dropped or duplicated inputs"); App.Capture(window, Path.Combine(directory, "batch-ready.png")); await window.Start(); Check(window.Plan.Entries.All(e => e.State == "Done"), "Batch UI did not run each row"); Check(Descendants<Button>(window).Count(x => Equals(x.Content, "Show output") && x.Visibility == Visibility.Visible) == 3, "Outputs are not reachable from every row"); App.Capture(window, Path.Combine(directory, "batch-complete.png")); } finally { window.Close(); } });
        await Test("Batch settings buttons open editors, share settings and retain a custom override", async () =>
        {
            var window = new BatchWindow(app, new[] { a, b }, Item("crop"), WheelMode.Tools, settings);
            try
            {
                window.Show(); await Task.Delay(80); var shared = Descendants<Button>(window).Single(x => Equals(x.Content, "Settings for all…"));
                _ = app.Dispatcher.BeginInvoke(() => shared.RaiseEvent(new RoutedEventArgs(Button.ClickEvent)));
                await Until(() => app.Windows.OfType<OptionsWindow>().Any(w => w.IsVisible)); var editor = app.Windows.OfType<OptionsWindow>().Single(w => w.IsVisible); await editor.Ready;
                void Value(OptionsWindow target, string key, string value) => Descendants<TextBox>(target).Single(t => AutomationProperties.GetName(t) == key).Text = value;
                Value(editor, "Width", "100"); Value(editor, "Height", "60"); editor.PrimaryAction.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));
                await Until(() => window.Plan.CommonOptions != null); Check(window.Plan.CommonOptions!.Width == 100, "Shared editor did not update the plan");
                var edit = Descendants<Button>(window).Single(x => AutomationProperties.GetName(x) == "Edit " + Path.GetFileName(b)); _ = app.Dispatcher.BeginInvoke(() => edit.RaiseEvent(new RoutedEventArgs(Button.ClickEvent)));
                await Until(() => app.Windows.OfType<OptionsWindow>().Any(w => w.IsVisible)); editor = app.Windows.OfType<OptionsWindow>().Single(w => w.IsVisible); await editor.Ready;
                Check(editor.ReadOptions().Width == 200, "Shared crop was not scaled in individual preview"); Value(editor, "Width", "40"); Value(editor, "Height", "30"); editor.PrimaryAction.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));
                await Until(() => window.Plan.Entries[1].CustomOptions != null); await Task.Delay(100); App.Capture(window, Path.Combine(directory, "batch-crop-settings.png"));
                var apply = Descendants<Button>(window).Single(x => Equals(x.Content, "Apply to 2 files")); apply.RaiseEvent(new RoutedEventArgs(Button.ClickEvent)); await window.Completion;
                using var result = new MagickImage(window.Plan.Entries[1].Outputs.Single()); Check(result.Width == 40 && result.Height == 30 && window.Plan.Entries.All(e => e.State == "Done"), "Batch UI ignored custom options");
            }
            finally { foreach (var child in app.Windows.OfType<OptionsWindow>().Where(w => w.IsVisible).ToArray()) child.Close(); window.Close(); }
        });
        await Test("Native OLE drop carries three files through the wheel into the batch panel", async () =>
        {
            Native.GetCursorPos(out var cursor); var savedOutput = app.Settings.OutputDirectory; app.Settings.OutputDirectory = output;
            var trace = new List<string>(); OverlayWindow.Diagnostic = message => trace.Add(message);
            var source = new Window { Title = "Tangerine batch drag check", Width = 240, Height = 130, Left = 40, Top = 40, Topmost = true }; var surface = new Border { Background = Brushes.WhiteSmoke, Child = PanelUi.Text("Multi-file drag check") }; source.Content = surface;
            OverlayWindow? overlay = null;
            try
            {
                source.Show(); source.Activate(); await Task.Delay(100); var point = surface.PointToScreen(new Point(40, 35)); var began = new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously); Point destination = new();
                await Task.Run(async () =>
                {
                    SetCursorPos((int)point.X, (int)point.Y); MouseEvent(2, 0, 0, 0, UIntPtr.Zero); await Task.Delay(100);
                    _ = app.Dispatcher.BeginInvoke(() => { overlay = new OverlayWindow(app, Array.Empty<string>(), WheelMode.Convert, true) { Left = 450, Top = 90 }; overlay.Show(); overlay.UpdateLayout(); destination = overlay.TopPetalScreenPoint; began.TrySetResult(); DragDrop.DoDragDrop(surface, new DataObject(DataFormats.FileDrop, images), DragDropEffects.Copy); });
                    await began.Task.WaitAsync(TimeSpan.FromSeconds(5)); await Task.Delay(120); SetCursorPos((int)destination.X, (int)destination.Y); await Task.Delay(350); SetCursorPos((int)destination.X, (int)destination.Y); MouseEvent(4, 0, 0, 0, UIntPtr.Zero);
                });
                await Until(() => app.Windows.OfType<BatchWindow>().Any(w => w.IsVisible)); var batch = app.Windows.OfType<BatchWindow>().Single(w => w.IsVisible);
                try { Check(batch.Plan.Entries.Count == 3 && batch.Plan.Item.Id == "jpg", "OLE selection was lost or wrong wheel item was invoked"); await batch.Start(); Check(batch.Plan.Entries.All(e => e.State == "Done"), "Native dropped batch failed"); App.Capture(batch, Path.Combine(directory, "batch-native-drop.png")); } finally { batch.Close(); }
            }
            finally { MouseEvent(4, 0, 0, 0, UIntPtr.Zero); overlay?.Close(); source.Close(); SetCursorPos(cursor.X, cursor.Y); app.Settings.OutputDirectory = savedOutput; OverlayWindow.Diagnostic = null; File.WriteAllLines(Path.Combine(directory, "batch-drag-trace.txt"), trace); }
        });
        await Test("Main window uses the complete mixed selection for both wheels", () => { var window = new MainWindow(app); try { window.SetFiles(new[] { a, pdf }); var wheel = (RadialWheel)window.FindName("ConvertWheel"); Check(wheel.Items.Any(x => x.Id == "png") && !wheel.Items.Any(x => x.Id == "docx"), "Main window menu used only the first source"); } finally { window.Hide(); } return Task.CompletedTask; });
        await Test("Deep copies isolate mutable per-file selections", () => { var options = new OperationOptions { SnapshotTimes = new() { .2 }, PageEdits = new() { new(1) } }; var copy = options.Copy(); copy.SnapshotTimes.Add(1); copy.PageEdits.Clear(); Check(options.SnapshotTimes.Count == 1 && options.PageEdits.Count == 1, "Options lists were shared"); return Task.CompletedTask; });
        await Test("All original sources remain unchanged", () => { Check(hashes.All(x => x.Value.SequenceEqual(SHA256.HashData(File.ReadAllBytes(x.Key)))), "A source changed"); return Task.CompletedTask; });
        await Test("No staging directories remain after success, failure or cancellation", () => { Check(!Directory.GetDirectories(directory, ".tangerine-*", SearchOption.AllDirectories).Any(), "Leaked staging output"); return Task.CompletedTask; });
        File.WriteAllText(Path.Combine(directory, "complete.json"), JsonSerializer.Serialize(new { completed = true, checks = reports.Count, ApplicationDllSHA256 = Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(typeof(App).Assembly.Location))) }));
    }
    static IEnumerable<T> Descendants<T>(DependencyObject parent) where T : DependencyObject { for (int i = 0; i < VisualTreeHelper.GetChildrenCount(parent); i++) { var child = VisualTreeHelper.GetChild(parent, i); if (child is T value) yield return value; foreach (var item in Descendants<T>(child)) yield return item; } }
    static async Task Until(Func<bool> condition) { var watch = Stopwatch.StartNew(); while (!condition()) { if (watch.ElapsedMilliseconds > 10000) throw new TimeoutException("The expected UI state did not appear."); await Task.Delay(40); } }
    [DllImport("user32.dll")] static extern bool SetCursorPos(int x, int y);
    [DllImport("user32.dll", EntryPoint = "mouse_event")] static extern void MouseEvent(uint flags, uint x, uint y, uint data, UIntPtr extra);
}
